-- lovable-cron-fallback-reviewed: Queue-backed future schedules and daily provider resets have no delayed workflow; arm only while pending, unschedule after drain, immediate enqueue wake.
CREATE OR REPLACE FUNCTION public.email_wake_dispatch() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE secret text; BEGIN SELECT value INTO secret FROM public.internal_job_secrets WHERE name='cron'; IF secret IS NOT NULL THEN PERFORM net.http_post(url:='https://xellvio.com/api/public/email/dispatch',headers:=jsonb_build_object('Content-Type','application/json','x-cron-secret',secret),body:='{}'::jsonb,timeout_milliseconds:=60000); END IF; END $$; REVOKE ALL ON FUNCTION public.email_wake_dispatch() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_wake_dispatch() TO service_role;
CREATE OR REPLACE FUNCTION public.email_arm_dispatch() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j bigint; pending boolean; BEGIN PERFORM pg_advisory_xact_lock(hashtext('email-dispatch-scheduler')); SELECT EXISTS(SELECT 1 FROM public.email_recipients r JOIN public.email_campaigns c ON c.id=r.campaign_id WHERE r.status IN ('queued','sending') AND c.status IN ('queued','sending')) INTO pending; SELECT jobid INTO j FROM cron.job WHERE jobname='email-pending-dispatch'; IF pending AND j IS NULL THEN PERFORM cron.schedule('email-pending-dispatch','*/5 * * * *','SELECT public.email_wake_dispatch()'); ELSIF NOT pending AND j IS NOT NULL THEN PERFORM cron.unschedule(j); END IF; IF pending THEN PERFORM public.email_wake_dispatch(); END IF; END $$; REVOKE ALL ON FUNCTION public.email_arm_dispatch() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_arm_dispatch() TO service_role;
CREATE OR REPLACE FUNCTION public.email_recipient_eligible(_id uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.email_recipients r JOIN public.email_campaigns c ON c.id=r.campaign_id JOIN public.accounts a ON a.id=r.account_id JOIN public.email_bundles b ON b.account_id=r.account_id JOIN public.email_sending_domains d ON d.account_id=r.account_id AND d.domain=split_part(c.from_email,'@',2) AND d.status='verified' JOIN public.consents co ON co.profile_id=r.profile_id AND co.channel='email' AND co.status='subscribed' WHERE r.id=_id AND r.status='sending' AND c.status IN ('queued','sending') AND a.suspended_at IS NULL AND a.sending_suspended_at IS NULL AND b.status='active' AND b.period_end>now() AND NOT EXISTS(SELECT 1 FROM public.email_suppressions s WHERE s.account_id=r.account_id AND s.email=r.email)); $$; REVOKE ALL ON FUNCTION public.email_recipient_eligible(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_recipient_eligible(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.email_finish_campaigns() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.email_campaigns c SET status='submitted',updated_at=now() WHERE c.status IN ('queued','sending') AND NOT EXISTS(SELECT 1 FROM public.email_recipients r WHERE r.campaign_id=c.id AND r.status IN ('queued','sending')); $$; REVOKE ALL ON FUNCTION public.email_finish_campaigns() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_finish_campaigns() TO service_role;
CREATE OR REPLACE FUNCTION public.email_reserve_test(_account uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.email_bundles; cap public.email_provider_capacity; BEGIN INSERT INTO public.email_bundles(account_id) VALUES(_account) ON CONFLICT DO NOTHING; SELECT * INTO b FROM public.email_bundles WHERE account_id=_account FOR UPDATE; IF EXISTS(SELECT 1 FROM public.accounts WHERE id=_account AND (suspended_at IS NOT NULL OR sending_suspended_at IS NOT NULL)) THEN RAISE EXCEPTION 'Sending is on hold'; END IF; IF b.plan='free' AND b.period_end<=now() THEN UPDATE public.email_bundles SET used=0,period_start=date_trunc('month',now()),period_end=date_trunc('month',now())+interval '1 month' WHERE account_id=_account RETURNING * INTO b; END IF; IF b.status<>'active' OR b.period_end<=now() OR (b.email_limit IS NOT NULL AND b.used>=b.email_limit) THEN RAISE EXCEPTION 'Monthly email allowance exhausted or bundle needs renewal'; END IF; INSERT INTO public.email_provider_capacity(id) VALUES(true) ON CONFLICT DO NOTHING; SELECT * INTO cap FROM public.email_provider_capacity WHERE id=true FOR UPDATE; IF cap.day<>CURRENT_DATE THEN UPDATE public.email_provider_capacity SET day=CURRENT_DATE,used=0 WHERE id=true RETURNING * INTO cap; END IF; IF cap.used>=cap.daily_limit THEN RAISE EXCEPTION 'Daily email capacity reached. Try after the next daily reset.'; END IF; UPDATE public.email_provider_capacity SET used=used+1 WHERE id=true; UPDATE public.email_bundles SET used=used+1 WHERE account_id=_account; END $$; REVOKE ALL ON FUNCTION public.email_reserve_test(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_reserve_test(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.email_apply_event(_event_id text,_recipient uuid,_event text,_at timestamptz,_reason text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.email_recipients; BEGIN INSERT INTO public.email_event_receipts(event_id) VALUES(_event_id) ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN; END IF; SELECT * INTO r FROM public.email_recipients WHERE id=_recipient FOR UPDATE; IF NOT FOUND THEN RETURN; END IF; IF _event='delivered' THEN UPDATE public.email_recipients SET accepted_at=coalesce(accepted_at,_at),delivered_at=coalesce(delivered_at,_at),status=CASE WHEN status IN ('complaint','unsubscribed','bounced') THEN status ELSE 'delivered' END,updated_at=now() WHERE id=r.id; ELSIF _event='processed' THEN UPDATE public.email_recipients SET accepted_at=coalesce(accepted_at,_at),status=CASE WHEN status IN ('queued','sending','unconfirmed') THEN 'accepted' ELSE status END WHERE id=r.id; ELSIF _event='open' THEN UPDATE public.email_recipients SET opened_at=coalesce(opened_at,_at) WHERE id=r.id; ELSIF _event='click' THEN UPDATE public.email_recipients SET clicked_at=coalesce(clicked_at,_at) WHERE id=r.id; ELSIF _event IN ('bounce','dropped','spamreport','unsubscribe','group_unsubscribe') THEN IF _event<>'dropped' THEN INSERT INTO public.email_suppressions(account_id,email,reason) VALUES(r.account_id,r.email,_event) ON CONFLICT DO NOTHING; UPDATE public.consents SET status='unsubscribed',updated_at=now() WHERE profile_id=r.profile_id AND channel='email'; END IF; UPDATE public.email_recipients SET status=CASE WHEN _event='spamreport' THEN 'complaint' WHEN _event IN ('unsubscribe','group_unsubscribe') THEN 'unsubscribed' ELSE 'bounced' END,last_error=_reason,updated_at=now() WHERE id=r.id; UPDATE public.email_recipients SET status='suppressed',updated_at=now() WHERE account_id=r.account_id AND email=r.email AND status='queued'; END IF; END $$; REVOKE ALL ON FUNCTION public.email_apply_event(text,uuid,text,timestamptz,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.email_apply_event(text,uuid,text,timestamptz,text) TO service_role;
SELECT cron.schedule('email-bundle-renewals','23 * * * *','SELECT public.email_renew_bundles()');